(ROOT/'web_trial.py').write_text('"""Bounded native Firefly UI arm; native browser fetch for identity and egress."""\nimport json,sys,datetime,time,pathlib,hashlib,base64\nfrom urllib.parse import urlparse\nfrom playwright.sync_api import sync_playwright\ncfg=json.load(sys.stdin);P=pathlib.Path(\'/control\'); stop=False;tokens={}; current_job=0\nassert cfg[\'account_id\']==1739 and cfg[\'max_jobs\']==6 and cfg[\'interval_sec\']==180\nstart=datetime.datetime.fromisoformat(cfg[\'start_at\']).timestamp();end=start+1200\nassert 10<start-time.time()<120\n\ndef now():return datetime.datetime.now(datetime.timezone.utc).isoformat()\ndef sha(v):return hashlib.sha256(str(v).encode()).hexdigest()\ndef emit(kind,**kwargs):\n with (P/\'web-trial.jsonl\').open(\'a\') as f:f.write(json.dumps({\'at\':now(),\'event\':kind,\'account_id\':1739,\'job\':current_job,**kwargs},ensure_ascii=False)+\'\\n\')\ndef claims(token):\n try:\n  s=token.split(\'.\')[1];return json.loads(base64.urlsafe_b64decode(s+\'=\'*(-len(s)%4)))\n except Exception:return {}\ndef safe_fields(d):\n out={}\n def visit(v,path=\'\'):\n  if not isinstance(v,dict):return\n  for k,val in v.items():\n   key=k.lower().replace(\'_\',\'\')\n   if key in [\'model\',\'modelid\',\'modelversion\',\'modelspecifier\',\'numvariations\',\'aspectratio\',\'outputresolution\',\'status\',\'state\',\'errorcode\',\'code\',\'width\',\'height\'] and isinstance(val,(str,int,float,bool)) and len(str(val))<160:out[path+k]=val\n   if isinstance(val,dict):visit(val,path+k+\'.\')\n   if isinstance(val,list):\n    for i,x in enumerate(val[:4]):\n     if isinstance(x,dict):visit(x,path+k+\'.\'+str(i)+\'.\')\n visit(d);return out\n\ndef request(r):\n u=urlparse(r.url)\n if not u.hostname or not any(u.hostname.endswith(x) for x in [\'adobe.io\',\'adobelogin.com\',\'adobe.com\']):return\n auth=r.headers.get(\'authorization\',\'\');token=auth[7:] if auth.lower().startswith(\'bearer \') else \'\'\n if token and claims(token).get(\'client_id\')==\'clio-playground-web\':tokens[sha(token)]=token\n if not token and not (\'/ims/\' in u.path):return\n fields={\'method\':r.method,\'host\':u.hostname,\'path\':u.path[:180],\'token_sha256\':sha(token) if token else None,\'arp_sha256\':sha(r.headers.get(\'x-arp-session-id\',\'\')),\'arp_length\':len(r.headers.get(\'x-arp-session-id\',\'\'))}\n try:fields[\'payload\']=safe_fields(r.post_data_json)\n except Exception:pass\n emit(\'http_start\',**fields)\n\ndef response(r):\n global stop\n u=urlparse(r.url)\n if not u.hostname or not any(u.hostname.endswith(x) for x in [\'adobe.io\',\'adobelogin.com\',\'adobe.com\']):return\n auth=r.request.headers.get(\'authorization\',\'\')\n if not auth and \'/ims/\' not in u.path:return\n f={\'status\':r.status,\'host\':u.hostname,\'path\':u.path[:180]}\n if \'generate\' in u.path or \'async\' in u.path or \'job\' in u.path or r.status>=400:\n  try:f[\'fields\']=safe_fields(r.json())\n  except Exception:pass\n emit(\'http_finish\',**f)\n if r.status==401 and (\'firefly\' in u.hostname or \'clio\' in u.hostname or \'/ims/profile\' in u.path):stop=True;emit(\'stop\',reason=\'upstream_401\')\n\nwith sync_playwright() as pw:\n browser=pw.chromium.connect_over_cdp(\'http://127.0.0.1:9222\');ctx=next(c for c in browser.contexts if c.pages)\n page=next(p for p in ctx.pages if urlparse(p.url).hostname==\'firefly.adobe.com\')\n ctx.on(\'request\',request);ctx.on(\'response\',response)\n initial=json.loads(pathlib.Path(\'/tmp/selected-web-token.json\').read_text());tokens[sha(initial[\'token\'])]=initial[\'token\']\n def check():\n  global stop\n  token=list(tokens.values())[-1]\n  result=page.evaluate(\'\'\'async token => { const p=await fetch(\'https://ims-na1.adobelogin.com/ims/profile/v1\',{headers:{Authorization:\'Bearer \'+token,\'X-Client-Id\':\'clio-playground-web\'}});let d={};try{d=await p.json()}catch{};const r=await fetch(\'https://api.ipify.org?format=json\');const ip=await r.json();return {profile_status:p.status,email:d.email||\'\',ip:ip.ip}}\'\'\',token)\n  iphash=sha(result[\'ip\']);identity=result[\'profile_status\']==200 and result[\'email\'].lower()==cfg[\'email\'].lower()\n  emit(\'identity_egress\',profile_status=result[\'profile_status\'],identity_matches=identity,ip_sha256=iphash,token_sha256=sha(token))\n  if not identity or not iphash.startswith(cfg[\'ip_sha256\']):stop=True;emit(\'stop\',reason=\'identity_or_egress_changed\')\n check()\n while time.time()<start and not stop:page.wait_for_timeout(300)\n emit(\'account_start\',arm=\'real_firefly_web_low_frequency\',interval_sec=180,max_jobs=6,model=cfg[\'model\'])\n next_check=time.time()+60\n for job in range(1,7):\n  target=start+(job-1)*180\n  while time.time()<target and not stop:\n   if (P/\'stop-web-trial\').exists():stop=True;break\n   if time.time()>=next_check:\n    try:check()\n    except Exception as e:stop=True;emit(\'stop\',reason=\'identity_check_failed\',error_class=type(e).__name__)\n    next_check=time.time()+60\n   page.wait_for_timeout(500)\n  if stop or time.time()>=end:break\n  current_job=job\n  assert cfg[\'model_ui_text\'] in page.locator(\'sp-picker#model\').locator(\'button#button\').inner_text()\n  page.get_by_role(\'textbox\',name=\'Prompt\',exact=True).fill(\'A simple red apple on a plain white background.\')\n  emit(\'job_start\')\n  page.get_by_role(\'button\',name=cfg[\'generate_button\'],exact=True).click(timeout=10000)\n  page.wait_for_timeout(25000)\n  emit(\'ui_after_click\',text=page.locator(\'body\').inner_text()[:6500])\n while time.time()<end and not stop:\n  if (P/\'stop-web-trial\').exists():stop=True;break\n  if time.time()>=next_check:\n   try:check()\n   except Exception as e:stop=True;emit(\'stop\',reason=\'identity_check_failed\',error_class=type(e).__name__)\n   next_check=time.time()+60\n  page.wait_for_timeout(500)\n # Accepted work may finish after stop; no replay.\n if stop:page.wait_for_timeout(180000)\n emit(\'account_done\',jobs_clicked=current_job,stopped=stop,text=page.locator(\'body\').inner_text()[:6500])\n')

