old=[]
for pp in pathlib.Path('/proc').iterdir():
 if not pp.name.isdigit():continue
 try:args=(pp/'cmdline').read_bytes().split(b'\0');args=[x.decode() for x in args if x]
 except (OSError,UnicodeError):continue
 if len(args)==3 and args[1:]==[str(ROOT/'isolation.py'),'watchdog']:old.append(int(pp.name))
assert len(old)==1,'must identify only owned previous watchdog'
watch=subprocess.Popen(['python3',str(ROOT/'watchdog_v2.py')],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,start_new_session=True)
assert watch.poll() is None
os.kill(old[0],signal.SIGTERM)
save('watchdog-extension.json',{'at':now(),'old_pid':old[0],'new_pid':watch.pid,'new_deadline':'2026-10-27T12:15:00Z','scope':'selected diagnostic isolation only'})
f=open(ROOT/'trial-controller-process.log','a')
